package com.sudoplatform.sudoprivacyinteraction.types.inputs

/**
 * Input object containing the properties required to list scan summaries for a data holder.
 *
 * @property dataHolderId [String] The identifier of the data holder to list scan summaries for.
 * @property limit [Int] Number of items to return.
 * @property nextToken [String] A token generated by a previous call, used for pagination.
 */
data class ListDataHolderScanSummariesInput(
    val dataHolderId: String,
    val limit: Int? = null,
    val nextToken: String? = null,
)
